mapper.select:
SELECT TNA.* FROM TBL_PROJECT_DATAPRE TNA 

   1=1
    ${secrectSql}

        AND  TNA.projectId = #{dataProVo.projectId}


        and (id in (select dataid from TBL_DATAPROJECT_ISSUE where staffid=#{dataProVo.staffid})
        OR TNA.CREATESTAFF = #{dataProVo.staffid})


        AND TNA.ORGID  = #{dataProVo.orgid}


        AND TNA.PROJECT_DATAPRE_ID like concat(concat('%',#{dataProVo.datacode}),'%')


        AND TNA.DATA_NAME like concat(concat('%',#{dataProVo.dataname}),'%')



       ORDER BY TNA.ID DESC
